-- create unitTests from ServiceProviderCreator.lua

local ServiceProviderCreator = require(script.Parent.ServiceProviderCreator)
local ServiceCollection = require(script.Parent.ServiceCollection)

-- make type provider
local mockTypeB = {
	IsGenericType = false,
	GetConstructors = function()
		return {
			{
				GetParameters = function()
					return { { ParameterType = { FullName = "TypeA" } } }
				end,
			},
		}
	end,
}

local mockLuaTypeProvider = {
	IsLuaTypeProvider = true,
	GetType = function(typeName)
		if typeName == "testService" then
			return mockTypeB
		end
		if typeName == "TypeB" then
			return mockTypeB
		end
	end,
}

return function()
	describe("ServiceProviderCreator", function()
		-- it("应该能够创建一个服务提供者", function()
		-- 	local creator = ServiceProviderCreator.new(mockLuaTypeProvider)
		-- 	local provider = creator:Build()

		-- 	expect(provider).to.be.ok()
		-- 	expect(type(provider)).to.equal("table")
		-- end)

		it("应该能够注册和解析服务", function()
			local collection = ServiceCollection.new()
			collection:AddSingleton("testService", function()
				return { value = "测试" }
			end)

			local creator = ServiceProviderCreator.new(collection, mockLuaTypeProvider)
			local provider = creator:Build()
			local service = provider:GetService("testService")

			expect(service).to.be.ok()
			expect(service.value).to.equal("测试")
		end)

		it("add hosted service", function()
			local runCount = 0
			local collection = ServiceCollection.new()
			collection:AddHostedService(function()
				runCount += 1
				return { value = "测试" }
			end)
			collection:AddHostedService(function()
				runCount += 1
				return { value = "测试1" }
			end)
			collection:AddHostedService(function()
				runCount += 1
				return { value = "测试2" }
			end)

			local creator = ServiceProviderCreator.new(collection, mockLuaTypeProvider)
			local host = creator:Build()
		end)
	end)
end
